static constexpr int LINE_WIDTH = 60;

static unsigned char compl_map[256];

static void init_map() {
    for (int i = 0; i < 256; ++i)
        compl_map[i] = static_cast<unsigned char>(i);

    const char* from = "ACGTUMRYKVHDBNSWacgtumrykvhdbnsw";
    const char* to   = "TGCAAYRKMDBHVNSWTGCAAYRKMDBHVNSW";
    for (int i = 0; from[i]; ++i)
        compl_map[static_cast<unsigned char>(from[i])] = static_cast<unsigned char>(to[i]);
}

static void reverse_complement(char* s, char* e) {
    while (s < e) {
        --e;
        unsigned char a = compl_map[static_cast<unsigned char>(*s)];
        unsigned char b = compl_map[static_cast<unsigned char>(*e)];
        *s = static_cast<char>(b);
        *e = static_cast<char>(a);
        ++s;
    }
}

static void write_wrapped(const char* s, size_t n) {
    size_t pos = 0;
    while (pos + static_cast<size_t>(LINE_WIDTH) <= n) {
        std::fwrite(s + pos, 1, static_cast<size_t>(LINE_WIDTH), stdout);
        std::fputc('\n', stdout);
        pos += static_cast<size_t>(LINE_WIDTH);
    }
    if (pos < n) {
        std::fwrite(s + pos, 1, n - pos, stdout);
        std::fputc('\n', stdout);
    }
}

