struct Node {
    Node* left;
    Node* right;
};

static Node* make(int depth, Node*& next) {
    Node* n = next++;
    if (depth > 0) {
        n->left = make(depth - 1, next);
        n->right = make(depth - 1, next);
    } else {
        n->left = n->right = nullptr;
    }
    return n;
}

static int check(const Node* n) {
    if (!n->left)
        return 1;
    return 1 + check(n->left) + check(n->right);
}

static int make_check(int depth, Node* buf) {
    Node* next = buf;
    Node* t = make(depth, next);
    return check(t);
}

static Node* alloc_nodes(std::size_t count) {
    return static_cast<Node*>(std::malloc(sizeof(Node) * count));
}

