static inline int nuc_code(char c) {
    switch (c) {
        case 'A': case 'a': return 0;
        case 'C': case 'c': return 1;
        case 'G': case 'g': return 2;
        case 'T': case 't': return 3;
        default: return -1;
    }
}

static const char NUC[] = "ACGT";

static std::vector<uint8_t> load_sequence(size_t reserve_hint) {
    std::string data;
    data.reserve(reserve_hint ? reserve_hint + (reserve_hint >> 2) + 4096 : (1u << 20));
    char buf[1 << 16];
    for (;;) {
        size_t n = std::fread(buf, 1, sizeof(buf), stdin);
        if (n == 0) break;
        data.append(buf, n);
    }

    size_t i = 0;
    size_t p = data.find(">THREE");
    if (p != std::string::npos) {
        i = data.find('\n', p);
        if (i == std::string::npos) return {};
        ++i;
    }

    std::vector<uint8_t> seq;
    seq.reserve(reserve_hint ? reserve_hint : (data.size() > i ? data.size() - i : 0));
    for (; i < data.size(); ++i) {
        char c = data[i];
        if (c == '>') break;
        int code = nuc_code(c);
        if (code >= 0) seq.push_back(static_cast<uint8_t>(code));
    }
    return seq;
}

static uint64_t encode_pattern(const char* s, int& k) {
    uint64_t h = 0;
    k = 0;
    for (; s[k]; ++k) {
        h = (h << 2) | static_cast<uint64_t>(nuc_code(s[k]));
    }
    return h;
}

static int count_kmer(const std::vector<uint8_t>& seq, const char* pat) {
    int k = 0;
    uint64_t need = encode_pattern(pat, k);
    const size_t n = seq.size();
    if (k <= 0 || n < static_cast<size_t>(k)) return 0;
    const uint64_t mask = (k >= 32) ? ~0ULL : ((1ULL << (2 * k)) - 1ULL);
    uint64_t h = 0;
    for (int i = 0; i < k; ++i) h = (h << 2) | seq[i];
    int cnt = (h == need);
    for (size_t i = static_cast<size_t>(k); i < n; ++i) {
        h = ((h << 2) | seq[i]) & mask;
        cnt += (h == need);
    }
    return cnt;
}

struct Freq {
    char s[4];
    int count;
};

static void print_freqs(const std::vector<uint8_t>& seq, int k) {
    const size_t n = seq.size();
    const size_t total = (n >= static_cast<size_t>(k)) ? (n - static_cast<size_t>(k) + 1) : 0;
    const int nkeys = 1 << (2 * k);
    std::vector<int> counts(static_cast<size_t>(nkeys), 0);
    if (total > 0) {
        const uint64_t mask = (1ULL << (2 * k)) - 1ULL;
        uint64_t h = 0;
        for (int i = 0; i < k - 1; ++i) h = (h << 2) | seq[i];
        for (size_t i = static_cast<size_t>(k - 1); i < n; ++i) {
            h = ((h << 2) | seq[i]) & mask;
            counts[static_cast<size_t>(h)]++;
        }
    }

    std::vector<Freq> items;
    items.reserve(static_cast<size_t>(nkeys));
