    });
    for (const auto& it : items) {
        double pct = total ? (100.0 * static_cast<double>(it.count) / static_cast<double>(total)) : 0.0;
        std::printf("%s %.3f\n", it.s, pct);
    }
    std::printf("\n");
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    const int N = std::atoi(argv[1]);
    const size_t three_len = (N > 0) ? static_cast<size_t>(N) * 5u : 0u;

    std::vector<uint8_t> seq = load_sequence(three_len);

    print_freqs(seq, 1);
    print_freqs(seq, 2);

    static const char* frags[] = {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };
    for (const char* f : frags) {
        std::printf("%d\t%s\n", count_kmer(seq, f), f);
    }
    return 0;
}
